<div class="tool-grid">
    <div class="tool-field"><label>County / town</label><input data-input="location" value="Nairobi"></div>
    <div class="tool-field"><label>Area type</label><select data-input="area"><option value="major">Major urban area</option><option value="town">Town centre</option><option value="estate">Estate / apartment block</option><option value="rural">Rural / remote area</option></select></div>
    <div class="tool-field"><label>Property type</label><select data-input="property"><option value="business">Business / office</option><option value="home">Home</option><option value="estate">Gated estate</option><option value="school">School / institution</option></select></div>
    <div class="tool-field"><label>Distance from main road (metres)</label><input data-input="road" type="number" min="0" value="80"></div>
    <div class="tool-field"><label>Existing duct or poles?</label><select data-input="duct"><option value="yes">Yes</option><option value="unknown">Not sure</option><option value="no">No</option></select></div>
    <div class="tool-field"><label>Urgency</label><select data-input="urgency"><option value="normal">Normal</option><option value="soon">Need within 2 weeks</option><option value="urgent">Urgent</option></select></div>
</div>
<button class="tool-button mt-3" type="button" data-calculate>Check Coverage Likelihood</button>
